#!/usr/bin/env node
/**
 * End-to-end smoke test for the membership tool.
 *
 * Assumes:
 *  - Next.js dev server on :3000
 *  - DFRI verifier on :8080 (public) and :8443 (mTLS)
 *  - test certificates generated by tools/dfri-verifier/generate-test-certs.sh
 *  - MEMBERSHIP_ENABLE_DEV_TOOLS is on (the default outside production)
 *
 *   node tools/membership-smoke-test.mjs
 *
 * The mock purchase goes through the real ledger and access checks. It is a
 * development test: it does not prove that an EVM payment would be verified
 * against a live chain.
 */

import { request as httpRequest } from "node:http";
import { request as httpsRequest } from "node:https";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

const CERTS = resolve("tools/dfri-verifier/certs");
const results = [];

function fetchText({ url, method = "GET", body, cert = true }) {
  return new Promise((resolvePromise, reject) => {
    const isHttps = url.startsWith("https:");
    const requestFn = isHttps ? httpsRequest : httpRequest;
    const headers = {};
    if (body !== undefined) headers["content-type"] = "application/json";
    const req = requestFn(
      url,
      {
        method,
        headers,
        ...(cert && isHttps
          ? {
              cert: readFileSync(`${CERTS}/test-person-001.crt.pem`),
              key: readFileSync(`${CERTS}/test-person-001.key.pem`),
              ca: readFileSync(`${CERTS}/ca-bundle.crt.pem`),
              rejectUnauthorized: true,
            }
          : { rejectUnauthorized: false }),
      },
      (res) => {
        let text = "";
        res.setEncoding("utf8");
        res.on("data", (chunk) => (text += chunk));
        res.on("end", () =>
          resolvePromise({
            status: res.statusCode,
            headers: res.headers,
            text,
          }),
        );
      },
    );
    req.on("error", reject);
    if (body !== undefined) req.write(JSON.stringify(body));
    req.end();
  });
}

function check(name, condition, detail) {
  results.push({ name, ok: Boolean(condition) });
  console.log(
    `${condition ? "PASS" : "FAIL"}  ${name}${detail ? ` — ${detail}` : ""}`,
  );
}

async function main() {
  const selftest = await fetchText({
    url: "https://localhost:8443/api/membership/dev/selftest",
  });
  const selftestBody = JSON.parse(selftest.text);
  check(
    "domain self test passes",
    selftest.status === 200 && selftestBody.ok === true,
    `${selftestBody.passed}/${selftestBody.total} checks`,
  );
  for (const entry of selftestBody.checks ?? []) {
    if (!entry.ok)
      console.log(`      failed: ${entry.name} — ${entry.detail ?? ""}`);
  }

  const publicMembership = await fetchText({
    url: "http://localhost:8080/membership",
    cert: false,
  });
  check(
    "public membership page renders without an identity",
    publicMembership.status === 200 &&
      publicMembership.text.includes("Purchase access") &&
      publicMembership.text.includes("Sign in with DFRI-eID"),
    `HTTP ${publicMembership.status}`,
  );

  check(
    "public membership page explains the HoloFuel limitation",
    publicMembership.text.includes("HoloFuel") &&
      publicMembership.text.includes("cannot be paid from a web checkout yet"),
  );

  const secureMembership = await fetchText({
    url: "https://localhost:8443/membership",
  });
  check(
    "signed-in membership page shows the verified identity",
    secureMembership.status === 200 &&
      secureMembership.text.includes("test-person-001"),
    `HTTP ${secureMembership.status}`,
  );

  const purchase = await fetchText({
    url: "https://localhost:8443/api/membership/dev/mock-purchase",
    method: "POST",
    body: { planId: "plan_supporter_yearly" },
  });
  let purchaseBody = {};
  try {
    purchaseBody = JSON.parse(purchase.text);
  } catch {
    purchaseBody = {};
  }
  check(
    "mock purchase grants a real membership record",
    purchase.status === 200 &&
      purchaseBody.ok === true &&
      purchaseBody.membership?.active === true,
    purchaseBody.membership
      ? `${purchaseBody.membership.plan} until ${purchaseBody.membership.expiresAt}`
      : purchase.text.slice(0, 120),
  );

  const internal = await fetchText({ url: "https://localhost:8443/internal" });
  check(
    "member area opens for an identity with a membership",
    internal.status === 200 &&
      (internal.text.includes("Membership active") ||
        internal.text.includes("Administrator access")),
    `HTTP ${internal.status}`,
  );

  const admin = await fetchText({
    url: "https://localhost:8443/internal/members",
  });
  check(
    "admin board lists members, payments and audit events",
    admin.status === 200 &&
      admin.text.includes("Members and payments") &&
      admin.text.includes("Active memberships") &&
      admin.text.includes("Recent audit events"),
    `HTTP ${admin.status}`,
  );

  const library = await fetchText({
    url: "https://localhost:8443/internal/library",
  });
  check(
    "members' library opens for a paid member",
    library.status === 200 &&
      library.text.includes("Reading room") &&
      library.text.includes("figures/fig2-lattice.svg"),
    `HTTP ${library.status}`,
  );

  const withoutCert = await fetchText({
    url: "https://localhost:8443/internal",
    cert: false,
  });
  check(
    "secure port still rejects requests without a certificate",
    withoutCert.status === 401,
    `HTTP ${withoutCert.status}`,
  );

  const failed = results.filter((entry) => !entry.ok);
  console.log(
    `\n${results.length - failed.length}/${results.length} checks passed`,
  );
  if (failed.length > 0) process.exitCode = 1;
}

main().catch((error) => {
  console.error("Smoke test error:", error.message);
  process.exitCode = 1;
});
